// ===========================================================================
//  hd_mode7_linebuf.v
//  Phase 2 / B-fix – True HD Mode 7: Dual-Port Scanline Pixel Buffer
//
//  Fixes applied (Phase B):
//   * The read address is generated by an INTERNAL counter in the clk_vid
//     domain. The old hd_x_out input was an undriven top-level port
//     (synthesized to 0), so the buffer always read linebuf[0] and the
//     HD path silently did nothing. (Phase B1)
//   * Arming is now PER-LINE. The previous code cleared `armed` on
//     frame_out, which left HD output enabled on top of stale/partial
//     data for ~261 lines per frame. (Phase B3)
//   * All sys->vid crossings (armed handshake AND hblank) go through
//     2-FF synchronizers. (Phase B4)
//
//  Architecture
//  ============
//  Port A  (write, clk_sys — DMA reader / ARM-facing domain)
//    · Written one pixel at a time by the DMA reader.
//    · buf_arm pulses for one clk_sys cycle when a full line is written.
//
//  Port B  (read, clk_vid — video/display domain)
//    · `hblank_in` arrives from the PPU (clk_sys domain); it is
//      synchronized into clk_vid internally. Everything else — line
//      detection, read counter, output gating — is derived from the
//      synchronized version, so no external line_start is needed.
//    · Output drives HD_PIXEL_IN into the PPU video mux.
//
//  Arming / Line Sync
//  ==================
//  The DMA reader asserts buf_arm for one clk_sys cycle after writing a
//  complete scanline. A toggle handshake carries that pulse safely into
//  clk_vid. `armed` is set on the synchronized pulse and cleared on the
//  synchronized hblank rising edge (end of one line's active display),
//  so the ARM must re-write + re-arm every line. This is the correct
//  per-line behavior.
//
// ===========================================================================
module hd_mode7_linebuf
(
    input             clk_sys,        // ARM/DMA write domain
    input             clk_vid,        // Video read domain

    // --- Port A: DMA write interface (clk_sys) ---
    input      [10:0] buf_wr_addr,
    input      [23:0] buf_wr_data,
    input             buf_wr_en,
    input             buf_arm,

    // --- Port B: video read interface ---
    input             hblank_in,     // from PPU (clk_sys domain)
    input      [10:0] hd_width,      // pixels per HD line (e.g. 1024 at 4x)

    // --- Outputs to PPU mux (clk_vid) ---
    output reg [23:0] hd_pixel_in,
    output reg        hd_mode7_en
);

    reg [23:0] linebuf [0:2047];

    // ---------------------------------------------------------------------
    // Port A: synchronous write (sys domain)
    // ---------------------------------------------------------------------
    always @(posedge clk_sys) begin
        if (buf_wr_en)
            linebuf[buf_wr_addr] <= buf_wr_data;
    end

    // ---------------------------------------------------------------------
    // sys -> vid clock-domain crossing for the arm pulse.
    //   armed_req toggles in sys each time buf_arm pulses.
    //   Three FFs in vid synchronize it; an edge detector emits a
    //   one-cycle vid-domain "new arm" pulse.
    // ---------------------------------------------------------------------
    reg armed_req = 1'b0;
    always @(posedge clk_sys) begin
        if (buf_arm)     armed_req <= ~armed_req;
    end

    reg armed_s1, armed_s2, armed_s3;
    always @(posedge clk_vid) begin
        armed_s1 <= armed_req;
        armed_s2 <= armed_s1;
        armed_s3 <= armed_s2;
    end
    wire new_arm_pulse = (armed_s2 != armed_s3);

    // ---------------------------------------------------------------------
    // sys -> vid clock-domain crossing for hblank.
    //   hblank_in is a level signal from the PPU (sys). Synchronize it,
    //   then edge-detect the rising edge to mark "line just ended".
    // ---------------------------------------------------------------------
    reg hb_s1, hb_s2, hb_s3;
    always @(posedge clk_vid) begin
        hb_s1 <= hblank_in;
        hb_s2 <= hb_s1;
        hb_s3 <= hb_s2;
    end
    wire hblank     = hb_s2;
    wire line_ended = hb_s2 & ~hb_s3;   // rising edge of hblank

    // ---------------------------------------------------------------------
    // armed flag (vid domain). Set by a new arm pulse, cleared at the end
    // of each line's active display.
    // ---------------------------------------------------------------------
    reg armed = 1'b0;
    always @(posedge clk_vid) begin
        if (line_ended)    armed <= 1'b0;
        else if (new_arm_pulse) armed <= 1'b1;
    end

    // ---------------------------------------------------------------------
    // Internal read counter (Phase B1 fix). Increments through the active
    // region of each scanline; held at 0 during hblank. This is the SOLE
    // source of the linebuf read address — no external hd_x_out.
    // ---------------------------------------------------------------------
    reg [10:0] rd_x = 11'd0;
    wire in_active = ~hblank;

    always @(posedge clk_vid) begin
        if (!in_active)         rd_x <= 11'd0;
        else if (rd_x < hd_width) rd_x <= rd_x + 11'd1;
    end

    // ---------------------------------------------------------------------
    // Port B: synchronous read + output pipeline (vid domain)
    // ---------------------------------------------------------------------
    reg [23:0] rd_data;
    always @(posedge clk_vid) begin
        rd_data <= linebuf[rd_x];
    end

    always @(posedge clk_vid) begin
        hd_pixel_in <= rd_data;
        hd_mode7_en <= armed & in_active;
    end

endmodule
